import{c as e,n as t,s as n,t as r}from"./reading-catalog-contract-HSvgPmNc.js";var i=[`A`,`B`,`C`,`D`,`E`,`F`,`G`];function a({slug:e,title:a,topic:o,cefr:s,distractor:c,headingOrder:l,items:u}){let d=u.map(([e])=>e).concat(c),f=l.map(e=>d[e]),p={id:`${r}.task10.${e}`,revision:1,kind:`task10`,title:a,topic:o,cefr:s,provenance:`original`,validation:{contract:t},task:{texts:u.map(([,e],t)=>({id:i[t],text:e})),headings:f,answers:u.map((e,t)=>l.indexOf(t)),evidence:u.map(([,,e,t],n)=>({position:i[n],answer:l.indexOf(n),quote:e,explanationRu:t}))}};return n(p),p}var o=e([a({slug:`school-volunteers`,title:`Small actions around school`,topic:`school-volunteering`,cefr:`B1`,distractor:`A Fundraiser That Became a Concert`,headingOrder:[3,7,0,5,2,6,1,4],items:[[`A Quieter Lunch Break`,`The school library used to close at lunchtime because the librarian had other duties. Four students now take turns at the front desk after receiving basic training. Pupils can read, finish homework or simply escape the noisy dining hall, while the librarian checks the room from her nearby office.`,`Pupils can read, finish homework or simply escape the noisy dining hall`,`Главная мысль в том, что дежурство учеников открыло спокойное место во время обеда.`],[`Lessons Across Generations`,`Maya noticed that several older residents found smartphone menus confusing. She invited them to a weekly drop-in session at school, where teenagers explain one useful function at a time. The visitors learn to send photographs or book appointments, and the pupils become more patient teachers.`,`teenagers explain one useful function at a time`,`Текст описывает взаимное обучение подростков и пожилых людей работе со смартфонами.`],[`A Garden With a Second Purpose`,`Behind the sports hall, an unused corner has become a vegetable garden. Students grow beans, herbs and tomatoes there during science club meetings. They taste some of the produce themselves, but most of each harvest goes to a neighbourhood kitchen that prepares free meals.`,`most of each harvest goes to a neighbourhood kitchen`,`Урожай выращивают не только для школы: его основная часть помогает бесплатной кухне.`],[`Making New Students Feel Welcome`,`Arriving halfway through the school year can feel lonely. The buddy team pairs each new pupil with someone who knows the building and its routines. Buddies show practical things such as where to borrow sports equipment, but they also introduce classmates and invite newcomers to clubs.`,`they also introduce classmates and invite newcomers to clubs`,`Суть инициативы — помочь новичкам освоиться и быстрее войти в школьное сообщество.`],[`From Rubbish to Useful Supplies`,`Art club members collect clean packaging that would normally be thrown away. Cardboard becomes model buildings, fabric offcuts turn into costume decorations, and glass jars hold paintbrushes. The project has reduced the club’s shopping bill and made students think before putting materials in the bin.`,`The project has reduced the club’s shopping bill`,`Повторное использование упаковки даёт материал для творчества и сокращает расходы кружка.`],[`Reading for an Audience`,`Some younger children at the local hospital cannot hold a book comfortably. Student volunteers record short stories in a quiet classroom and add a friendly introduction to each one. Hospital staff put the recordings on tablets, so children can listen even when an adult reader is unavailable.`,`Student volunteers record short stories in a quiet classroom`,`Ученики записывают рассказы, чтобы дети в больнице могли слушать их самостоятельно.`],[`A Team Built Around Animals`,`At weekends, a group of classmates helps at an animal shelter. One person prepares food, another washes bowls, and two others write short profiles for the adoption page. The work is divided according to confidence and experience, so even a nervous first-time volunteer has a useful role.`,`even a nervous first-time volunteer has a useful role`,`Работа в приюте организована командно, и подходящее дело находится каждому участнику.`]]}),a({slug:`useful-technology`,title:`Technology solving ordinary problems`,topic:`everyday-technology`,cefr:`B1`,distractor:`Winning an International Gaming Tournament`,headingOrder:[6,1,4,0,7,2,5,3],items:[[`Knowing When the Bus Will Come`,`People at our village stop used to wait without knowing whether the bus was late. A student built a simple screen that uses public transport data and shows the next arrival. It does not make buses faster, but passengers can now decide whether there is time to visit the nearby shop.`,`uses public transport data and shows the next arrival`,`Экран сообщает время прибытия автобуса и помогает пассажирам разумно использовать ожидание.`],[`Family Recipes Saved Online`,`Lena’s grandmother kept her recipes on loose pieces of paper, and some were becoming difficult to read. Together they typed the instructions, photographed the finished dishes and added notes about family celebrations. Relatives in other cities can now cook the same food and contribute their own memories.`,`Relatives in other cities can now cook the same food`,`Цифровой сборник сохраняет семейные рецепты и делает их доступными далёким родственникам.`],[`A Timer That Protects Concentration`,`During revision, Pavel often reached for his phone without noticing. He installed a timer that blocks entertainment apps for twenty-five minutes and then allows a short break. The tool cannot do the studying for him, yet the clear intervals make long homework sessions feel manageable.`,`blocks entertainment apps for twenty-five minutes`,`Таймер временно закрывает отвлекающие приложения и поддерживает сосредоточенную работу.`],[`Mapping Easier Routes for Everyone`,`A youth group is creating an online map of the town centre. Instead of listing cafés, it marks ramps, dropped kerbs, quiet entrances and working lifts. Wheelchair users and parents with pushchairs test each route before it appears, which makes the information more reliable than guesses from photographs.`,`marks ramps, dropped kerbs, quiet entrances and working lifts`,`Карта собирает проверенные сведения о доступных маршрутах для людей с разными потребностями.`],[`Returning Lost Property Faster`,`The sports centre once stored unnamed jackets and bottles in a crowded cupboard. Staff now attach a small code to every found object and record where it was discovered. Visitors describe their missing item online, and the system suggests possible matches without publishing anyone’s personal details.`,`the system suggests possible matches`,`Система учёта сопоставляет описания с найденными вещами и ускоряет их возврат.`],[`Weather Data From the School Roof`,`A tiny sensor on the school roof records temperature, wind and rainfall every hour. Science classes compare today’s readings with older figures and look for patterns. The device has made local weather more than a topic in a textbook because pupils can investigate information collected above their own classroom.`,`pupils can investigate information collected above their own classroom`,`Собственный датчик превращает местную погоду в реальные данные для школьных исследований.`],[`Conversation Practice Across Borders`,`Two schools in different countries organise short video calls between language learners. Partners receive a topic but no complete script, so they must listen and respond naturally. At first many pupils fear making mistakes; after several calls, they speak more freely and ask better follow-up questions.`,`after several calls, they speak more freely`,`Регулярные видеобеседы с ровесниками помогают увереннее использовать иностранный язык.`]]}),a({slug:`healthy-routines`,title:`Healthy habits that fit real life`,topic:`teen-wellbeing`,cefr:`B1`,distractor:`Training for a Professional Sports Career`,headingOrder:[2,5,7,1,4,0,3,6],items:[[`Regular Hours Matter More Than One Long Sleep`,`Nikita used to sleep very little on school nights and stay in bed until noon on Sunday. He still felt tired on Monday. A nurse suggested moving bedtime gradually and keeping weekend hours closer to weekdays. After a month, getting up became easier even though his total Sunday sleep was shorter.`,`keeping weekend hours closer to weekdays`,`Улучшение связано со стабильным режимом, а не с одной очень долгой воскресной ночью.`],[`Company Makes Walking Easier`,`A group of neighbours meets for a brisk walk three evenings a week. Nobody competes or records the fastest time. Members say that conversation makes the distance pass quickly, and knowing that others are waiting helps them leave the sofa when the weather looks unattractive.`,`knowing that others are waiting helps them leave the sofa`,`Совместная прогулка поддерживает мотивацию благодаря общению и ответственности перед группой.`],[`Lunch Prepared Before the Rush`,`Buying lunch every day was expensive, and the quickest choices were not always filling. Now Sara prepares rice, vegetables and a simple protein on Sunday evening. She divides them into boxes and changes the sauce each day, so weekday meals require little time without becoming exactly the same.`,`weekday meals require little time without becoming exactly the same`,`Заранее приготовленная основа экономит время, а разные соусы сохраняют разнообразие обедов.`],[`Resting the Eyes, Not Ending the Work`,`After online lessons, Amir often had dry eyes and a headache. His teacher showed the class a simple pause: every twenty minutes, look at something far away for a short time. These brief changes of focus do not interrupt a lesson, but they reduce the strain of staring at one distance.`,`they reduce the strain of staring at one distance`,`Короткий взгляд вдаль разгружает глаза, не заставляя полностью прекращать занятие.`],[`Music as a Bridge Out of Stress`,`Before important tests, Elena listens to one calm playlist while packing her bag. The familiar songs slow her thoughts and also mark the end of revision. Music does not remove every worry, but this repeated signal helps her stop checking notes and begin the evening more peacefully.`,`this repeated signal helps her stop checking notes`,`Знакомая музыка служит устойчивым сигналом завершить подготовку и снизить напряжение.`],[`A Bottle That Shows Progress`,`Dan often returned home with most of his water untouched. He drew three small lines on a reusable bottle for morning, lunchtime and afternoon. The marks are not a medical target; they simply remind him to drink regularly instead of trying to remember everything at the end of the day.`,`they simply remind him to drink regularly`,`Метки на бутылке распределяют напоминания в течение дня и делают привычку заметной.`],[`One Screen-Free Morning`,`The Cho family does not ban phones for the whole weekend. On Saturday mornings, however, everyone leaves devices in a drawer until lunch. They cook, shop or visit the park together. Because the rule is limited and predictable, even the teenagers find it easier to follow.`,`Because the rule is limited and predictable`,`Ограниченный по времени семейный отказ от экранов оказывается реалистичным и выполнимым.`]]}),a({slug:`local-journeys`,title:`Learning through short journeys`,topic:`local-travel`,cefr:`B1`,distractor:`A Luxury Hotel With No Guests`,headingOrder:[7,4,1,6,0,3,5,2],items:[[`A Delay That Revealed a Town`,`When our train was cancelled, the next service was three hours later. Instead of sitting at the station, we left our bags in a locker and followed a walking route through the old centre. The delay remained inconvenient, but it gave us a place we had never planned to explore.`,`it gave us a place we had never planned to explore`,`Неожиданная задержка превратилась в возможность познакомиться с незапланированным городом.`],[`Staying With a Family Changes the Visit`,`During an exchange week, I lived with a family rather than in a hotel. Breakfast conversations taught me everyday expressions that never appeared in class. I also learned why local people ate dinner later than my family, so ordinary routines became an important part of the trip.`,`ordinary routines became an important part of the trip`,`Проживание в семье позволило узнать язык и культуру через повседневную жизнь.`],[`Following a River by Bicycle`,`The new cycle path follows the river for twenty kilometres and avoids the main road. Signs show the distance to villages, water points and repair stations. Because most of the route is level, our mixed group stayed together and spent more time watching birds than worrying about speed.`,`the route is level, our mixed group stayed together`,`Ровная безопасная велодорожка подходит группе с разной подготовкой и позволяет наблюдать природу.`],[`One Backpack, Fewer Decisions`,`For a two-day trip, Rosa packed only a small backpack. She chose clothes that could be worn in several combinations and downloaded documents instead of carrying printed copies. With fewer objects to manage, changing buses was simpler and she spent less time checking whether something was missing.`,`With fewer objects to manage, changing buses was simpler`,`Лёгкий багаж уменьшил количество забот и упростил пересадки во время короткой поездки.`],[`A Guide Who Asked Questions`,`Our museum guide did not speak for an entire hour. She first showed us an unfamiliar object and asked what we thought it was used for. Each answer led to another clue. By the time she explained its history, the group had already examined it closely and wanted to know more.`,`Each answer led to another clue`,`Экскурсовод вовлекает посетителей вопросами и подсказками вместо непрерывной лекции.`],[`Rain Was Part of the Plan`,`The forecast promised showers throughout our coastal walk. We packed waterproof layers and chose a route with several cafés and bus stops. Rain changed the view and shortened one section, but it did not ruin the day because we had planned flexible places to pause or finish.`,`we had planned flexible places to pause or finish`,`Гибкий маршрут и подходящая одежда позволили продолжить прогулку несмотря на дождь.`],[`The Market Explained the Region`,`At the weekend market, producers sold cheese, honey and bread from nearby villages. Small cards described where each product came from and how the landscape affected it. Tasting the food helped us understand the region better than simply buying a standard souvenir from the station.`,`Tasting the food helped us understand the region`,`Местные продукты на рынке раскрыли особенности края лучше обычного сувенира.`]]}),a({slug:`student-journalism`,title:`Inside a student newsroom`,topic:`school-media`,cefr:`B2`,distractor:`Advertising That Paid for New Classrooms`,headingOrder:[5,2,0,7,4,1,6,3],items:[[`Questions Before Conclusions`,`When a rumour spread that the canteen would close, the student newspaper did not publish it immediately. Reporters asked the head teacher, the catering company and pupils who had heard the claim. They discovered that only one serving area would close for repairs, turning an alarming story into an accurate practical notice.`,`Reporters asked the head teacher, the catering company and pupils`,`Редакция проверила слух у нескольких сторон и заменила сенсацию точной информацией.`],[`A Photograph Needs Its Own Investigation`,`A dramatic photograph can attract readers, but it may hide what happened before or afterwards. Our editors now request the time, place and original file for every submitted image. Last month this rule revealed that a supposedly recent flood picture had actually been taken in another town two years earlier.`,`request the time, place and original file`,`Проверка происхождения фотографии помогает не выдавать старый чужой снимок за свежую новость.`],[`Giving Quiet People Space to Answer`,`Fast interviews often favour the most confident speaker. For a feature about exam pressure, reporters offered students a choice between a live conversation and written questions. Several thoughtful responses arrived the next day from pupils who would not have spoken near a microphone, making the article broader and less predictable.`,`offered students a choice between a live conversation and written questions`,`Разные способы ответа позволили услышать тех, кому неудобно говорить сразу и публично.`],[`Corrections Should Be Easy to Find`,`The first issue of our newspaper hid mistakes in a tiny note on the final page. Readers understandably missed it. The editorial team now places every correction beside the online version of the original article and explains what changed, so accuracy is treated as an ongoing responsibility rather than a private embarrassment.`,`places every correction beside the online version of the original article`,`Исправления публикуются рядом с исходным материалом, поэтому читателю легко увидеть изменения.`],[`When Numbers Need a Human Story`,`A survey showed that forty percent of students cycled to school, but the figure alone explained little. Reporters followed three cyclists on different routes and recorded the obstacles they met. Their experiences showed why safe crossings mattered, giving the percentage a clear meaning without pretending three stories represented everyone.`,`Their experiences showed why safe crossings mattered`,`Личные истории объяснили значение сухой статистики, сохранив честное ограничение выборки.`],[`The Headline Must Keep Its Promise`,`One draft carried the headline “School Abandons Music”, although the article only described a timetable change. Editors replaced it with a calmer, more precise line. Fewer people clicked at first, yet readers stayed longer because the story delivered exactly what its title had led them to expect.`,`the story delivered exactly what its title had led them to expect`,`Точный заголовок не преувеличивает содержание и укрепляет доверие читателей.`],[`A Podcast Adds Voices, Not Just Sound`,`The newspaper’s first podcast simply read printed articles aloud and attracted little interest. The team redesigned it around short interviews, background sounds from school events and reporters explaining choices they made. Listening now offers material that the page cannot provide instead of duplicating the same product.`,`Listening now offers material that the page cannot provide`,`Подкаст стал самостоятельным форматом благодаря интервью, звуковой среде и авторским комментариям.`]]}),a({slug:`city-wildlife`,title:`Wildlife sharing the city`,topic:`urban-nature`,cefr:`B2`,distractor:`The Zoo That Released Every Animal`,headingOrder:[1,6,3,5,7,0,2,4],items:[[`Dark Corridors for Night Travellers`,`A row of bright lamps made a riverside path feel safer to people but disrupted bats feeding there. The council fitted lower lights with warm colours and switched some off after midnight. Residents kept a visible route, while the darker strip above the water again served animals moving through the city.`,`the darker strip above the water again served animals moving through the city`,`Изменённое освещение сохраняет путь людям и одновременно возвращает ночной коридор летучим мышам.`],[`Tiny Gardens Joining a Larger Network`,`One balcony planter cannot support an entire insect population. Across several streets, however, residents are growing native flowers that bloom at different times. Together the small patches provide a chain of food stops from spring to autumn, allowing bees and butterflies to cross an area dominated by concrete.`,`small patches provide a chain of food stops`,`Множество небольших посадок образует связанную сеть питания для городских насекомых.`],[`Listening Instead of Looking`,`Students surveying birds in a wooded park rarely saw every species hidden among the leaves. They learned to identify repeated calls and used short recordings only when uncertain. Sound revealed early-morning visitors that visual counting had missed, though the group still noted that traffic noise could distort its results.`,`Sound revealed early-morning visitors that visual counting had missed`,`Определение птиц по голосам обнаружило виды, незаметные при обычном визуальном наблюдении.`],[`A Roof That Slows the Rain`,`The plants on the sports centre roof were chosen for more than appearance. Their soil holds part of a heavy shower and releases it gradually, reducing pressure on street drains. On hot days the same layer also shades the roof surface, showing how one small habitat can support city infrastructure.`,`soil holds part of a heavy shower and releases it gradually`,`Озеленённая крыша задерживает ливневую воду и тем самым помогает городской системе стоков.`],[`Sharing Fruit With Urban Birds`,`People often hang feeders all year without checking what local birds actually need. A community orchard takes another approach: it leaves a few apples on selected trees after harvest. The fruit offers seasonal food, while volunteers remove anything rotten and avoid creating a permanent source that attracts too many animals.`,`leaves a few apples on selected trees after harvest`,`В саду специально сохраняют часть урожая как сезонный, контролируемый корм для птиц.`],[`A Passage Beneath the Road`,`Hedgehogs were repeatedly found near a busy road between two parks. During resurfacing, engineers added a narrow tunnel and guided animals towards it with low fencing. Motion cameras later recorded regular crossings, providing evidence that the hidden structure connected habitats more safely than warning signs alone.`,`Motion cameras later recorded regular crossings`,`Подземный проход с направляющими ограждениями доказанно связал два места обитания ежей.`],[`Citizen Records Need Careful Checking`,`An app lets residents upload photographs of foxes, insects and unusual plants. The volume is valuable, but an expert team checks location, date and identification before using a record in research. Rejected entries are not treated as failures; contributors receive notes that improve the quality of their next observation.`,`an expert team checks location, date and identification`,`Массовые наблюдения жителей становятся научными данными только после проверки специалистами.`]]}),a({slug:`learning-strategies`,title:`Ways to learn more effectively`,topic:`study-methods`,cefr:`B2`,distractor:`Why Every Subject Needs the Same Method`,headingOrder:[4,0,6,2,5,7,3,1],items:[[`Retrieval Shows What Is Missing`,`Reading a chapter repeatedly made the material feel familiar to Leon, but he could not explain it without the page. He began closing the book and writing everything he remembered before checking. The uncomfortable gaps became useful information: they showed exactly which ideas required another visit rather than another complete rereading.`,`The uncomfortable gaps became useful information`,`Попытка вспомнить без книги выявляет конкретные пробелы, которые скрывает простое перечитывание.`],[`Examples First, Rule Second`,`A maths teacher sometimes begins with three solved problems and asks the class what they share. Students compare the steps before receiving the formal rule. The approach takes longer at the start, yet the rule then answers a question learners have already formed instead of arriving as an isolated statement.`,`the rule then answers a question learners have already formed`,`Самостоятельное сравнение примеров создаёт потребность в правиле и облегчает его понимание.`],[`Explaining to an Imaginary Beginner`,`Before a biology test, Noor describes each process aloud as if speaking to a younger pupil. Whenever she relies on a vague phrase such as “and then it happens”, she marks that point for review. Teaching an imaginary beginner forces hidden assumptions into the open and turns fluent-sounding notes into a real check.`,`forces hidden assumptions into the open`,`Объяснение для новичка обнаруживает места, где знание подменено расплывчатой фразой.`],[`Mixing Problems to Practise Choosing`,`A worksheet containing twenty identical exercises makes the procedure obvious after the first few. Mixed practice combines several types without labels, so students must first decide which method applies. Their speed may fall during practice, but the final task resembles a test where nobody announces the required technique.`,`students must first decide which method applies`,`Смешанные упражнения тренируют выбор подхода, а не механическое повторение уже названного способа.`],[`Short Reviews Spread Across Time`,`Olga once saved vocabulary revision for a single long evening. Now she reviews a small set after one day, then after several days, and again the following week. Some words still disappear, but each successful return strengthens access more efficiently than keeping them briefly active in one session.`,`each successful return strengthens access`,`Повторения с увеличивающимися интервалами лучше укрепляют долговременное вспоминание слов.`],[`Changing the Study Setting Carefully`,`Always studying in one silent room can link recall to that particular setting. Dan occasionally reviews the same material in the kitchen or on a quiet bus, while keeping distractions limited. The variation is modest rather than chaotic, and it helps him practise finding knowledge under more than one set of conditions.`,`practise finding knowledge under more than one set of conditions`,`Умеренная смена обстановки делает воспоминание менее зависимым от одного привычного места.`],[`Feedback After a Real Attempt`,`In language class, students submit a first version before seeing the model answer. The teacher’s comments can therefore address choices they genuinely made. If the model came first, many would copy its structure and never discover their own difficulties with organisation, tone or evidence.`,`comments can therefore address choices they genuinely made`,`Обратная связь полезнее после самостоятельной попытки, потому что отвечает на реальные решения ученика.`]]}),a({slug:`sustainable-choices`,title:`Making everyday choices more sustainable`,topic:`sustainable-living`,cefr:`B2`,distractor:`Replacing Every Old Object Immediately`,headingOrder:[2,7,5,1,6,4,0,3],items:[[`Repair Becomes a Social Skill`,`At the monthly repair evening, visitors bring lamps, bicycles and torn clothes. Volunteers do not simply take the objects away and return them fixed; owners sit beside them and learn each step. The event keeps useful items in service while spreading practical knowledge beyond the few people who already have it.`,`owners sit beside them and learn each step`,`Ремонтная встреча одновременно продлевает жизнь вещам и передаёт навыки их владельцам.`],[`Borrowing What Is Rarely Needed`,`A drill may be essential for ten minutes and then remain in a cupboard for years. Our neighbourhood library now lends tools, carpet cleaners and camping equipment. Members reserve them online and report damage honestly, gaining access to occasional necessities without every household buying and storing its own copy.`,`gaining access to occasional necessities without every household buying`,`Библиотека вещей заменяет редкие покупки совместным доступом к нужному оборудованию.`],[`The Hidden Journey of a T-Shirt`,`A school display follows one cotton shirt from field to shop. Labels show the water used, the distance travelled and the work performed at each stage. Instead of telling visitors never to buy clothes, it helps them see why wearing an item longer can matter as much as choosing it.`,`why wearing an item longer can matter`,`История производства одежды показывает экологическую ценность более долгого использования вещи.`],[`Food Plans That Prevent Waste`,`The café once decided its menu before checking what remained from the previous day. It now records unsold ingredients and designs the next soup or sandwich around food that is still safe. Customers see a changing menu, while purchasing becomes more accurate and fewer usable vegetables reach the bin.`,`designs the next soup or sandwich around food that is still safe`,`Меню учитывает оставшиеся продукты, благодаря чему пригодная еда не выбрасывается.`],[`A Refill System Must Be Convenient`,`A shop introduced refill stations for soap and cereal, but few customers used them when containers had to be weighed at a distant counter. Moving the scales beside the dispensers and printing clear instructions changed behaviour quickly. The greener option succeeded only after it became as simple as the packaged one.`,`succeeded only after it became as simple as the packaged one`,`Экологичная система стала популярной после устранения неудобств для покупателей.`],[`Sharing the Results of Energy Changes`,`Students asked the school to switch off corridor lights when daylight was sufficient. After sensors were installed, the caretaker published monthly electricity figures rather than announcing victory. The visible reduction kept interest alive, while months with little change encouraged the group to investigate heating and computer use.`,`published monthly electricity figures rather than announcing victory`,`Открытые данные позволяют оценивать результат экономии и искать следующие источники расхода.`],[`A Longer Route With a Smaller Impact`,`Fresh berries flown across the world may arrive quickly, while preserved local fruit can wait in storage. A geography project compares transport, packaging and season rather than using distance alone. Students learn that the most sustainable choice depends on the whole journey, not one attractive number.`,`depends on the whole journey, not one attractive number`,`Оценка продукта учитывает транспорт, упаковку и сезонность, а не только километры.`]]}),a({slug:`community-culture`,title:`Culture created with a community`,topic:`local-culture`,cefr:`B2`,distractor:`A Famous Actor Refuses to Perform`,headingOrder:[6,3,1,5,0,2,7,4],items:[[`Memories Become Part of the Exhibition`,`For an exhibition about the old railway, the museum asked residents to bring tickets, photographs and recorded memories. Curators checked dates and added historical context, but the voices remained personal. The result describes not only engines and timetables but also how the station shaped departures, reunions and ordinary working lives.`,`Curators checked dates and added historical context, but the voices remained personal`,`Личные воспоминания жителей дополнили музейную историю железной дороги человеческим опытом.`],[`A Festival Uses More Than One Language`,`The neighbourhood festival once printed every sign only in the majority language. This year local families helped translate directions and short programme notes into four others. Not every performance needs translation, yet visitors can now find stages, understand safety information and feel that the event expects them.`,`visitors can now find stages, understand safety information`,`Многоязычные указатели делают фестиваль понятнее и гостеприимнее для разных жителей.`],[`The Audience Helps Shape the Play`,`A youth theatre is developing a play about online friendship. After early scenes, invited pupils discuss which moments feel believable and where characters seem too simple. The writers do not accept every suggestion, but repeated comments reveal confusion and help them create a story that respects the audience’s experience.`,`repeated comments reveal confusion and help them create a story`,`Отзывы будущих зрителей помогают драматургам исправлять неясные и неправдоподобные моменты.`],[`Old Songs Find New Arrangements`,`Members of a folk group taught traditional melodies to students from an electronic music club. Rather than placing a dance beat under every tune, the teams explored rhythm and meaning together. Some pieces remained nearly unchanged; others gained new textures that attracted listeners without treating tradition as decoration.`,`explored rhythm and meaning together`,`Совместная работа сохраняет смысл традиционных песен, одновременно позволяя современное звучание.`],[`A Mural Starts With Listening`,`Before painting the wall beside the market, artists held open meetings and collected drawings from nearby schools. Residents disagreed about colours but repeatedly mentioned the river and migrating birds. Those shared images became the centre of the design, so the finished mural belongs to the place rather than merely occupying it.`,`shared images became the centre of the design`,`Общие образы из обсуждений жителей легли в основу местной настенной росписи.`],[`Tickets Priced to Widen Access`,`The small concert hall introduced several ticket bands for the same performance. Full-price buyers can choose better seats, while a limited number remain available at a very low cost. The policy brings in less money per cheap seat, but empty places fall and students attend events they previously considered unaffordable.`,`students attend events they previously considered unaffordable`,`Разные ценовые категории расширили доступ к концертам и уменьшили число пустых мест.`],[`When the Archive Goes Outdoors`,`Boxes of historical photographs attracted few visitors in the local archive. Staff enlarged selected images and placed weatherproof copies exactly where each scene had been photographed. Walkers can compare past and present streets on site, while codes lead interested viewers back to the full digital collection.`,`compare past and present streets on site`,`Уличные копии архивных снимков позволяют сопоставить прежний и современный вид города.`]]}),a({slug:`first-jobs`,title:`What teenagers learn from first jobs`,topic:`teen-employment`,cefr:`B2`,distractor:`Becoming Rich Before Finishing School`,headingOrder:[0,4,7,2,6,1,3,5],items:[[`Questions Prevent Costly Guessing`,`On his first day in a bakery, Ilya was embarrassed to ask where special orders were stored. He guessed, placed two cakes on the wrong shelf and delayed a collection. His manager explained that a brief question is cheaper than silent uncertainty, a lesson he now applies before unfamiliar tasks.`,`a brief question is cheaper than silent uncertainty`,`Ошибка научила новичка заранее уточнять непонятное, а не скрывать сомнения.`],[`A Shift Is More Than Its Busy Hour`,`Mina expected café work to mean serving customers, but opening and closing routines took equal care. She learned to check deliveries, prepare change and leave clear notes for the morning team. These invisible tasks showed her that reliable service depends on work customers never see.`,`reliable service depends on work customers never see`,`Опыт в кафе раскрыл важность незаметной подготовки и передачи смены.`],[`Feedback Becomes Easier to Use`,`At a summer camp, Lev first heard every correction as criticism of his personality. His supervisor began naming the exact action, its effect and one possible improvement. Lev copied this pattern when helping younger volunteers, discovering that precise feedback can protect confidence while still changing behaviour.`,`precise feedback can protect confidence while still changing behaviour`,`Конкретная обратная связь отделяет поступок от личности и помогает совершенствоваться.`],[`The Schedule Teaches Honest Limits`,`Combining school with weekend retail work looked simple on paper. After accepting extra shifts, Hana missed deadlines and felt exhausted. She now blocks exam weeks in advance and refuses hours she cannot manage. Earning slightly less has made both her studying and her work more dependable.`,`refuses hours she cannot manage`,`Планирование и умение отказаться от лишних смен сохраняют качество учёбы и работы.`],[`Small Savings Need a Clear Purpose`,`Omar’s wages disappeared through small daily purchases until he chose a goal: a refurbished laptop for college. He arranged an automatic transfer after every payday and kept the rest available. The fixed purpose made saving feel like progress towards something real rather than punishment for spending.`,`The fixed purpose made saving feel like progress`,`Конкретная цель и автоматический перевод превратили накопление денег в заметный процесс.`],[`Mistakes Reveal a Better System`,`While shelving books, Alice repeatedly mixed two similar catalogue sections. Instead of relying on greater attention, she suggested coloured divider cards and a final trolley check. The library adopted both ideas, and errors fell for everyone, showing how a beginner’s difficulty can expose a weak process.`,`a beginner’s difficulty can expose a weak process`,`Повторяющаяся ошибка новичка помогла улучшить систему работы для всей библиотеки.`],[`Courtesy Has Practical Value`,`Delivering groceries by bicycle, Sam sometimes arrived after rain or roadworks had caused delays. A short message with an honest arrival estimate prevented most complaints. Customers did not demand perfect timing; they mainly wanted enough information to adjust their own plans instead of waiting without news.`,`they mainly wanted enough information to adjust their own plans`,`Вежливое предупреждение о задержке помогает клиентам планировать время и снижает недовольство.`]]}),a({slug:`everyday-science`,title:`Science hidden in daily routines`,topic:`science-literacy`,cefr:`B2`,distractor:`An Experiment That Proved Every Claim`,headingOrder:[3,6,2,7,1,5,0,4],items:[[`A Fair Test Changes One Thing`,`Students comparing paper towels first used different sheet sizes and amounts of water. Their results said more about the method than the brands. They repeated the trial with equal sheets, measured drops and identical waiting times, learning that control is what turns an impression into a useful comparison.`,`control is what turns an impression into a useful comparison`,`Справедливое сравнение требует одинаковых условий и изменения только проверяемого фактора.`],[`Why Bread Changes in the Fridge`,`Refrigeration slows mould, yet bread can become firm faster there than at room temperature. In a food science lesson, pupils learned that starch molecules rearrange in the cold. Freezing works differently, so families who cannot finish a loaf quickly may preserve texture better by freezing slices.`,`starch molecules rearrange in the cold`,`Изменение структуры крахмала объясняет, почему холодильник ускоряет черствение хлеба.`],[`A Shadow Can Measure Height`,`The astronomy club wanted the height of a flagpole without climbing it. At the same moment, members measured the pole’s shadow and the shadow of a metre stick. Because sunlight formed the same angle, the two proportions gave a reliable estimate with ordinary tape measures and some geometry.`,`the two proportions gave a reliable estimate`,`Соотношение одновременных теней позволяет точно вычислить высоту недоступного флагштока.`],[`Kitchen Steam Carries More Than Heat`,`Opening a pot lid releases hot vapour, but the cloud we see is made of tiny liquid drops formed as water cools. This distinction helped a class understand why a clear area appears closest to the opening before the white cloud. An everyday saucepan became a model of changing states.`,`tiny liquid drops formed as water cools`,`Видимое облако состоит из сконденсированных капель, а не из невидимого водяного пара.`],[`A Phone Sensor Becomes a Laboratory Tool`,`Modern phones contain sensors that detect movement and orientation. Physics students placed a secured device on a playground swing and exported its readings. The numbers were imperfect, but repeated patterns let them compare motion at different heights without buying specialist equipment.`,`repeated patterns let them compare motion at different heights`,`Датчики смартфона дают достаточно данных для сравнения движения школьной качели.`],[`Correlation Does Not Name the Cause`,`A class survey found that pupils who ate breakfast often reported better concentration. It could not show that breakfast alone caused the difference: sleep, family routines or other factors might influence both. The result suggested a question worth deeper study, not a rule that applied to every student.`,`suggested a question worth deeper study, not a rule`,`Связь двух показателей создаёт гипотезу, но не доказывает единственную причину.`],[`Cooling Faster With a Larger Surface`,`Two equal cups of tea were left for ten minutes, but one was poured into a wide shallow bowl. It cooled more quickly because more liquid was exposed to the surrounding air. The simple demonstration explains why spreading hot food on a plate changes its temperature faster.`,`more liquid was exposed to the surrounding air`,`Большая открытая поверхность заметно ускоряет отдачу тепла окружающему воздуху.`]]}),a({slug:`better-conversations`,title:`Building clearer conversations`,topic:`communication-skills`,cefr:`B2`,distractor:`Speaking the Loudest Wins Every Debate`,headingOrder:[5,1,4,7,2,6,0,3],items:[[`Checking Meaning Before Replying`,`During a project meeting, Eva thought “finish the design” meant producing the final poster, while her partner meant choosing a layout. Instead of working separately, she asked what result they expected by Friday. One short question exposed the difference and prevented two evenings of unnecessary work.`,`One short question exposed the difference`,`Уточняющий вопрос обнаружил разное понимание задачи до начала лишней работы.`],[`Silence Can Carry Different Messages`,`An exchange student worried that long pauses in conversation showed boredom. His host family explained that they often paused to consider an answer and regarded interruption as rude. Neither style was naturally better; recognising the difference stopped him from filling every quiet moment with nervous speech.`,`they often paused to consider an answer`,`Пауза оказалась культурным способом обдумать ответ, а не признаком отсутствия интереса.`],[`Restating a View You Oppose`,`Before responding in the debate club, each speaker must summarise the previous argument until its owner agrees the summary is fair. This rule slows the exchange, yet it removes easy misunderstandings. Participants still disagree strongly, but they challenge the real position rather than a weaker version they invented.`,`they challenge the real position rather than a weaker version`,`Честный пересказ чужой позиции направляет спор против настоящего аргумента, а не искажения.`],[`Tone Hides in Small Email Choices`,`A message saying “Send the file” may be efficient among close friends but abrupt to an unfamiliar teacher. Students compared greetings, modal verbs and closing lines across real situations. They found that politeness did not require a long email; a few framing words could make the same request easier to receive.`,`a few framing words could make the same request easier to receive`,`Небольшие языковые элементы меняют восприятие просьбы без ненужного увеличения письма.`],[`Making Room for Every Group Member`,`In one science team, two confident pupils answered every question while the others recorded notes silently. The group introduced rotating roles for explaining, checking and asking. Quieter members began contributing observations the team had missed, demonstrating that equal participation can improve the work itself, not only people’s feelings.`,`Quieter members began contributing observations the team had missed`,`Ротация ролей включила молчаливых участников и принесла группе новые полезные наблюдения.`],[`An Apology Needs a Next Step`,`After losing a borrowed camera cable, Theo said sorry several times but offered no solution. His friend remained frustrated because the problem still existed. Theo then ordered a replacement and arranged a temporary loan from the media room, turning regret into practical repair of both the situation and trust.`,`turning regret into practical repair`,`Извинение стало убедительным, когда к словам добавились конкретные действия по исправлению ущерба.`],[`A Drawing Bridges Specialist Language`,`Students planning a rain garden met an engineer who used unfamiliar drainage terms. Rather than pretending to understand, they sketched the site and asked her to mark how water would move. The shared diagram let both sides point to the same places and made a technical explanation accessible without removing its important detail.`,`The shared diagram let both sides point to the same places`,`Общий рисунок связал профессиональные термины с конкретными местами и движением воды.`]]}),a({slug:`neighbourhood-projects`,title:`Projects shaped by local residents`,topic:`community-participation`,cefr:`B2`,distractor:`A Mayor Who Made Every Decision Alone`,headingOrder:[2,6,0,5,3,1,7,4],items:[[`Young Residents Decide a Real Budget`,`The town gave its youth council a modest fund for one local improvement. Members collected proposals, checked costs with officials and opened an online vote for teenagers. The winning idea was shaded seating beside the sports ground, and participants could follow each invoice until construction ended.`,`opened an online vote for teenagers`,`Подростки не просто советовали властям, а сами выбрали проект и контролировали расход бюджета.`],[`A Skill Exchange Without Money`,`At the community centre, residents list something they can teach and something they hope to learn. A retired tailor offers basic repairs in return for help organising digital photographs; a student teaches guitar and learns bicycle maintenance. Time and knowledge circulate even when nobody can afford private lessons.`,`Time and knowledge circulate even when nobody can afford private lessons`,`Обмен навыками даёт участникам обучение через взаимную помощь без денежных расчётов.`],[`Clear Rules Keep Shared Food Safe`,`A public fridge reduces waste by accepting unopened or clearly labelled food. Volunteers record temperatures twice a day, remove expired items and publish a simple list of what cannot be donated. The restrictions may seem unfriendly, but they protect users and allow the service to remain open with public confidence.`,`they protect users and allow the service to remain open`,`Строгие правила хранения обеспечивают безопасность и доверие к общественному холодильнику.`],[`A Bus Stop Designed From Waiting`,`Architects first proposed a stylish shelter with a narrow metal seat. Local passengers invited them to wait there during wind and rain. The revised design added side panels, space for wheelchairs and a bench suitable for older people, because direct experience revealed needs that a drawing had hidden.`,`direct experience revealed needs that a drawing had hidden`,`Испытание остановки в реальных условиях выявило недостатки первоначального красивого проекта.`],[`Past Floods Guide Future Preparation`,`Residents marked on a large map where water had entered streets during previous storms. Engineers combined those memories with height measurements and drain records. Personal accounts were not perfectly precise, yet they highlighted overlooked corners and helped the town choose where more detailed surveys should begin.`,`they highlighted overlooked corners and helped the town`,`Воспоминания жителей дополнили технические данные и указали места для дальнейшего обследования.`],[`One Bench Creates Regular Contact`,`A housing association placed a bench near the entrance after older residents said they rarely met neighbours. The seat did not create instant friendship, but people began pausing there at similar times. Repeated brief greetings gradually made it easier to ask for help or share local information.`,`Repeated brief greetings gradually made it easier to ask for help`,`Регулярные короткие встречи у скамейки постепенно укрепили соседские связи и взаимопомощь.`],[`Tools Are Useful Only With Guidance`,`The new makerspace bought a laser cutter, sewing machines and electronics kits, then discovered that many visitors felt too nervous to touch them. Weekly beginner sessions now pair each machine with a small achievable project. Attendance rose because equipment became an invitation to make something, not an impressive display behind warnings.`,`equipment became an invitation to make something`,`Вводные занятия превратили сложное оборудование из пугающей витрины в доступный инструмент.`]]}),a({slug:`responsible-travel`,title:`Travelling with respect for a place`,topic:`responsible-tourism`,cefr:`B2`,distractor:`Collecting Rare Plants as Souvenirs`,headingOrder:[4,7,2,0,5,3,1,6],items:[[`A Different Season Spreads the Benefit`,`Visitors usually crowd the island during six summer weeks, leaving rooms empty for much of the year. A walking festival in early spring now attracts guests when guides and cafés need work most. Travellers accept cooler weather and receive quieter paths, while income reaches businesses beyond the peak.`,`income reaches businesses beyond the peak`,`Поездки весной уменьшают сезонный перекос и поддерживают местный бизнес вне летнего наплыва.`],[`Local Guides Add Living Knowledge`,`A castle brochure explains dates and architecture, but a guide from the nearby village also knows how the empty buildings are used today. She describes winter markets, school performances and recent restoration arguments. The historical site becomes part of a continuing community rather than a frozen background for photographs.`,`part of a continuing community rather than a frozen background`,`Местный гид связывает исторический памятник с современной жизнью окружающего сообщества.`],[`Distance Protects the Experience`,`Tourists approaching nesting seabirds often move closer for a better picture. Rangers have marked viewing points where lenses still capture the colony without causing adults to leave their nests. Watching from farther away may produce a less dramatic image, but it preserves the behaviour visitors came to observe.`,`it preserves the behaviour visitors came to observe`,`Соблюдение дистанции не тревожит птиц и сохраняет естественную сцену для наблюдения.`],[`Refilling Works When Water Is Trusted`,`A mountain town installed public taps to reduce disposable bottles, yet travellers avoided them because no information was provided. Signs now show test dates and local water standards, while hotels lend durable bottles. Use increased once visitors could see that convenience was supported by transparent safety checks.`,`Use increased once visitors could see`,`Открытые данные о проверках сделали систему питьевых кранов заслуживающей доверия.`],[`The Slower Route Supports More Stops`,`An express coach links the capital with the coast in two hours, bypassing several small towns. A regional pass encourages visitors to use local buses and break the journey overnight. The trip takes longer, but spending and attention are distributed among places that high-speed travel normally turns into scenery.`,`spending and attention are distributed among places`,`Медленный маршрут распределяет время туристов и их расходы между небольшими городами.`],[`Permission Comes Before the Portrait`,`At a craft market, some visitors photographed workers without speaking to them. Organisers added cards explaining how to ask permission and when photography interrupts delicate work. Most artisans welcome genuine interest; the new practice simply lets them choose how their image and workplace are recorded.`,`lets them choose how their image and workplace are recorded`,`Предварительное разрешение возвращает мастерам контроль над съёмкой их лица и работы.`],[`Accommodation Owned by the Community`,`A remote village converted an unused school into a small guesthouse. Local families take turns managing it, and profits fund the bus service and playground rather than leaving through an outside chain. Guests receive simple rooms, but their stay directly supports facilities residents use throughout the year.`,`profits fund the bus service and playground`,`Доход общественной гостиницы остаётся в деревне и оплачивает нужные жителям услуги.`]]}),a({slug:`creative-practice`,title:`How creative work develops`,topic:`creative-process`,cefr:`B2`,distractor:`Waiting for a Perfect Idea Before Starting`,headingOrder:[7,3,5,1,0,6,4,2],items:[[`Limits Can Produce More Original Choices`,`A film club challenged members to make a story using one room, two actors and no spoken dialogue. At first the rules seemed restrictive. Soon teams experimented with framing, sound and objects in ways they might have ignored with unlimited resources, proving that boundaries can direct imagination rather than merely reduce it.`,`proving that boundaries can direct imagination rather than merely reduce it`,`Ограничения заставили участников искать выразительные решения в кадре, звуке и предметах.`],[`A Sketchbook Trains Attention`,`Jia carries a small notebook but rarely tries to create finished drawings in it. She records the angle of a bicycle, a stranger’s posture or the shape of a shadow. Later these quick observations provide specific details for larger illustrations and prevent her from relying only on familiar symbols.`,`quick observations provide specific details for larger illustrations`,`Быстрые зарисовки собирают реальные детали, которые затем обогащают большие работы.`],[`Useful Criticism Describes an Effect`,`When readers said a story was “bad”, its author had no clear next step. A workshop asked them instead to identify where attention dropped, what they expected and which detail changed their view. Describing the reading experience gave the writer evidence for revision without pretending that personal taste had disappeared.`,`gave the writer evidence for revision`,`Конкретное описание реакции читателя подсказывает направление правки лучше общей отрицательной оценки.`],[`Unfinished Work Can Teach in Public`,`The design class held an exhibition of prototypes rather than polished products. Labels explained failed materials, unanswered questions and the next planned test. Visitors spent longer discussing the objects because they could see decisions still being made, and students received ideas while change remained possible.`,`students received ideas while change remained possible`,`Показ незавершённых прототипов привлёк обратную связь тогда, когда её ещё можно использовать.`],[`Two Styles Need a Shared Rule`,`A poet and an animator collaborated on a short video but initially competed for attention. They agreed that images would expand the setting while spoken lines carried the emotional change. This simple division did not erase either style; it gave each contribution a purpose the other did not duplicate.`,`gave each contribution a purpose the other did not duplicate`,`Согласованное распределение функций позволило двум видам искусства дополнять, а не заглушать друг друга.`],[`An Accident Suggests a New Technique`,`Blue ink spilled across Tomas’s nearly finished print. Before throwing it away, he tested water and pressure on the mark and noticed a cloud-like texture. He could not save the original design, but the experiment became a technique in his next series, turning loss into material knowledge.`,`the experiment became a technique in his next series`,`Неудачно испорченная работа привела художника к приёму для следующей серии.`],[`Testing a Design With Its Audience`,`Students created signs for a maze-like community clinic. Instead of asking visitors whether the signs looked attractive, they gave newcomers destinations and watched where they hesitated. Several elegant arrows proved ambiguous, so the final design used simpler shapes that helped people reach rooms without extra questions.`,`gave newcomers destinations and watched where they hesitated`,`Наблюдение за реальным поиском пути выявило неясность красивых, но непрактичных указателей.`]]}),a({slug:`sport-beyond-winning`,title:`What sport offers beyond results`,topic:`inclusive-sport`,cefr:`B2`,distractor:`A Champion Who Never Needed Practice`,headingOrder:[1,5,3,6,2,0,4,7],items:[[`Different Roles Keep an Event Moving`,`At the school running festival, not everyone wanted to race. Students measured the course, welcomed families, managed water stations and photographed finishes. Treating these jobs as part of the event rather than consolation prizes revealed organisational talents and let more pupils contribute to a successful day.`,`let more pupils contribute to a successful day`,`Разнообразные роли включили в спортивное событие учеников, которые не хотели участвовать в забеге.`],[`Rules Adapted Without Removing Challenge`,`A mixed basketball club includes players with different mobility. Coaches adjusted court zones and allowed extra time for some passes, but kept shared goals, scoring and tactical decisions. The changes remove unnecessary physical barriers while preserving the cooperation and uncertainty that make the game engaging.`,`remove unnecessary physical barriers while preserving the cooperation`,`Адаптация правил убирает лишние препятствия, сохраняя командную сложность и интерес игры.`],[`Recovery Is Part of the Training Plan`,`Marta once treated every rest day as lost progress and added hard sessions whenever competition approached. Persistent pain eventually stopped her for weeks. Her new schedule alternates demanding work with sleep, gentle movement and planned recovery, allowing the body to adapt rather than merely survive repeated stress.`,`allowing the body to adapt`,`Запланированное восстановление помогает организму укрепляться после нагрузки и предотвращает длительный перерыв.`],[`Data Supports, but Does Not Replace, Judgement`,`The rowing team uses watches to compare stroke rate and heart rate across sessions. Coaches also ask athletes about sleep, mood and technique because the numbers cannot explain every change. A high reading may signal effort, heat or anxiety, so decisions combine measurements with context rather than obeying a dashboard.`,`decisions combine measurements with context`,`Тренеры сопоставляют показатели устройств с самочувствием и условиями, а не доверяют цифре изолированно.`],[`Losing Reveals the Next Practice Goal`,`After a defeat, the volleyball team avoided blaming the final missed serve. Video showed that weak communication had created uncertain positions throughout the match. Players chose one call system to practise, turning disappointment into a specific shared task instead of treating the result as proof they lacked talent.`,`turning disappointment into a specific shared task`,`Анализ поражения выявил конкретную проблему общения и превратил её в цель тренировки.`],[`Local Facilities Change Who Can Participate`,`A talented swimmer travelled ninety minutes to the nearest suitable pool and considered giving up. The opening of a modest training lane in her district did not provide elite conditions, but it made regular practice compatible with school. Access, not motivation, had been the main obstacle.`,`Access, not motivation, had been the main obstacle`,`Близкий бассейн устранил транспортный барьер, который мешал регулярным занятиям способной спортсменки.`],[`Older Players Become Guides`,`The junior football club pairs each new member with a player from the older age group. Mentors explain routines, demonstrate warm-ups and check in after difficult matches. Coaches still teach technique, while the near-peer relationship gives beginners someone approachable for questions they may consider too small or embarrassing.`,`gives beginners someone approachable for questions`,`Старшие участники становятся доступными наставниками для бытовых и эмоциональных вопросов новичков.`]]}),a({slug:`digital-citizenship`,title:`Living responsibly in digital spaces`,topic:`digital-citizenship`,cefr:`B2+/C1`,distractor:`Why Anonymous Accounts Are Always Dishonest`,headingOrder:[3,7,1,6,4,0,2,5],items:[[`Consent Continues After Posting`,`A student agreed to appear in a club photograph, then later asked for its removal after receiving unwanted messages. The club deleted the image even though the original permission had been genuine. Its new policy treats consent as revisable, recognising that circulation can create consequences nobody predicted at publication.`,`Its new policy treats consent as revisable`,`Согласие на публикацию можно отозвать, когда распространение изображения создаёт неожиданные последствия.`],[`A Recommendation Is Not a Neutral List`,`Two classmates searching the same video platform received sharply different results because their earlier viewing had trained the recommendation system. The contrast helped them see a feed as a personalised selection optimised for attention, not a complete measure of what is popular, important or true.`,`a personalised selection optimised for attention`,`Лента формируется прежним поведением пользователя и не является нейтральной картиной мира.`],[`Context Can Reverse a Viral Clip`,`A short clip appeared to show a scientist dismissing climate risks, and thousands shared it angrily. The full interview revealed that she was quoting an argument before challenging it. Checking the surrounding minutes changed the sentence’s function, demonstrating how accurate words can still create a false impression when isolated.`,`she was quoting an argument before challenging it`,`Полная запись показала, что вирусная фраза была чужим тезисом перед его опровержением.`],[`Privacy Settings Need Repeated Attention`,`Ravi made his account private when he created it and assumed the decision was permanent. Later an update introduced a new location-sharing feature with a separate default. A monthly review now catches settings added after his first choice, because privacy is an ongoing practice rather than a box checked once.`,`privacy is an ongoing practice rather than a box checked once`,`Новые функции меняют риски, поэтому настройки конфиденциальности нужно периодически пересматривать.`],[`Correction Should Travel With the Error`,`The school media page deleted an inaccurate post about an event time and published a correction several hours later. Readers who had shared screenshots never saw it. Editors now add the correction to the original post before reposting, increasing the chance that updated information follows the same routes as the mistake.`,`updated information follows the same routes as the mistake`,`Исправление прикрепляют к исходной публикации, чтобы оно распространялось по тем же каналам.`],[`Small Friction Can Improve Sharing`,`A messaging app tested a pause before users forwarded articles they had not opened. The delay lasted only a few seconds and could be ignored, yet more people chose to read first. The design did not decide which sources were true; it created a moment in which an automatic action became a conscious one.`,`an automatic action became a conscious one`,`Короткая пауза перед пересылкой побуждает сначала открыть материал, не назначая истину за пользователя.`],[`Public Debate Still Needs Boundaries`,`A youth forum welcomes disagreement about town policy but removes posts that reveal private addresses or coordinate harassment. Moderators publish examples and an appeal process so enforcement can itself be questioned. The aim is not universal comfort; it is preserving argument without allowing participants to become targets.`,`preserving argument without allowing participants to become targets`,`Прозрачная модерация сохраняет острый спор, одновременно защищая людей от преследования.`]]}),a({slug:`human-centred-city`,title:`Designing cities around human experience`,topic:`urban-design`,cefr:`B2+/C1`,distractor:`The Tallest Building Solves Housing Alone`,headingOrder:[5,2,7,0,3,6,4,1],items:[[`Temporary Change Before Permanent Concrete`,`Before rebuilding a dangerous junction, planners used paint, planters and removable barriers to narrow one turn for six weeks. Traffic still moved, while cameras and interviews revealed whether crossings felt safer. The inexpensive trial exposed an unexpected delivery problem that could be corrected before permanent construction locked it in.`,`corrected before permanent construction locked it in`,`Временный макет позволил проверить безопасность и исправить проблему до дорогого строительства.`],[`Shade Is a Form of Transport Infrastructure`,`A technically walkable route to school crossed a wide square with no trees or shelter. During hotter months, families chose cars despite the short distance. Adding shaded edges and drinking water changed pedestrian use, showing that a path exists functionally only when ordinary people can tolerate its conditions.`,`a path exists functionally only when ordinary people can tolerate its conditions`,`Комфорт от тени и воды определяет реальную пригодность маршрута не меньше тротуара.`],[`Benches Communicate Who May Stay`,`A plaza contained plenty of space but nowhere to sit without buying something. After public benches were installed, teenagers, carers and delivery workers began using it between activities. The change turned a route through commercial territory into a place where presence did not depend on spending money.`,`presence did not depend on spending money`,`Бесплатные места для сидения сделали площадь доступной для пребывания без обязательной покупки.`],[`Sound Maps Reveal an Invisible Burden`,`Noise complaints were concentrated on streets where residents knew how to contact the council, creating an incomplete picture. Volunteers carried calibrated sensors along fixed routes at different times. Their map uncovered persistent noise beside housing that had generated few formal reports, redirecting attention from complaint volume to actual exposure.`,`redirecting attention from complaint volume to actual exposure`,`Измерения шума выявили нагрузку там, где жители редко подавали официальные жалобы.`],[`One Entrance Should Work for Everyone`,`A theatre renovation initially kept an accessible door around the side of the building. Disability groups argued that a separate route still imposed extra effort and visibility. The final plan created a gently sloped main entrance, making inclusion part of the shared arrival rather than an exception managed elsewhere.`,`inclusion part of the shared arrival rather than an exception`,`Общий пологий вход устраняет отдельный обходной маршрут и делает доступность нормой.`],[`Empty Ground Can Serve Several Timescales`,`A vacant lot awaited development that might not begin for five years. The city allowed movable sports equipment, raised gardens and a weekend market there under short leases. Nothing prevented future housing, but the land delivered present value instead of remaining fenced during a long planning process.`,`delivered present value instead of remaining fenced`,`Временные переносные функции используют пустующий участок до начала будущего строительства.`],[`Children Notice Different Obstacles`,`Adults reviewing a route to the playground focused on traffic speed. Children walking it with planners pointed out high hedges that hid corners, confusing signs and puddles forcing them near the road. Their smaller height and different attention revealed barriers that professional inspection had literally overlooked.`,`revealed barriers that professional inspection had literally overlooked`,`Совместная прогулка с детьми обнаружила препятствия, незаметные взрослым проектировщикам.`]]}),a({slug:`environmental-fieldwork`,title:`How environmental evidence is built`,topic:`environmental-research`,cefr:`B2+/C1`,distractor:`One Photograph Predicts the Entire Climate`,headingOrder:[2,4,0,6,1,7,5,3],items:[[`A Baseline Makes Change Visible`,`Volunteers celebrated when otters returned to a restored stream, but the project had recorded conditions for two years before construction. Those earlier measurements of water quality, fish and animal tracks made it possible to distinguish improvement from normal seasonal variation. Success became a comparison, not merely an exciting sighting.`,`Success became a comparison, not merely an exciting sighting`,`Исходные данные до восстановления позволяют отличить устойчивое улучшение от случайного наблюдения.`],[`Missing Data Has Its Own Pattern`,`A sensor network appeared to show cleaner air during winter storms. Researchers noticed, however, that several devices lost power precisely in the wettest weather. Treating blank periods as random would have produced a comforting but false trend, so the team redesigned the housings before interpreting the seasonal results.`,`several devices lost power precisely in the wettest weather`,`Пропуски возникали при определённой погоде и искажали вывод об улучшении воздуха.`],[`Local Names Guide Scientific Sampling`,`Fishers used several traditional names for narrow zones of a wetland that looked similar on satellite images. Ecologists asked what distinguished them and learned about subtle differences in current and soil. Sampling those zones separately revealed plant communities that a uniform grid would have combined and obscured.`,`Sampling those zones separately revealed plant communities`,`Местные названия подсказали учёным экологические различия, скрытые на спутниковом снимке.`],[`Replication Tests an Attractive Result`,`One pond study found that floating plants sharply reduced water temperature. Rather than announcing a general solution, another team repeated the measurements across ponds of different depth and shade. The effect remained, but its size varied, producing a less dramatic conclusion that managers could apply more realistically.`,`repeated the measurements across ponds of different depth and shade`,`Повторение в разных условиях проверило красивый результат и уточнило границы его действия.`],[`A Sample Can Miss the Quiet Majority`,`Researchers studying beach litter first counted only objects visible on weekend mornings. Clean-up groups had already removed much of the waste by then. Adding evening counts and records from volunteers changed both the total and the most common items, demonstrating that sampling time was shaping the apparent problem.`,`sampling time was shaping the apparent problem`,`Время наблюдения после уборки скрывало часть мусора и меняло картину его состава.`],[`Open Methods Invite Better Questions`,`A school published not only its river results but also maps, equipment limits and the instructions students followed. An outside hydrologist noticed that one location was sampled after rain while others were not. Because the method was visible, the criticism could improve the next survey instead of simply challenging its credibility.`,`the criticism could improve the next survey`,`Публикация методики позволила специалисту обнаружить несопоставимое условие и улучшить исследование.`],[`Uncertainty Belongs on the Map`,`A wildlife map originally coloured every area as suitable or unsuitable for a rare butterfly. Yet observations were sparse in several remote valleys. The revised version marks confidence separately, preventing absence of reports from appearing identical to confirmed absence and directing future fieldwork to the least known places.`,`The revised version marks confidence separately`,`Отдельная отметка уверенности не позволяет путать нехватку наблюдений с доказанным отсутствием вида.`]]}),a({slug:`changing-education`,title:`Education for a changing world`,topic:`future-learning`,cefr:`B2+/C1`,distractor:`A Single Qualification Guarantees Lifelong Success`,headingOrder:[7,1,5,3,0,4,2,6],items:[[`Learning Portfolios Show Revision`,`A final project displays what a student achieved but often hides how the work improved. Digital portfolios can include early drafts, feedback and a short account of decisions. Employers or universities then see not just a polished outcome, but evidence that the learner can respond, revise and explain growth.`,`evidence that the learner can respond, revise and explain growth`,`Портфолио с черновиками показывает способность учитывать отзывы и осознанно улучшать результат.`],[`Short Credentials Need a Coherent Path`,`Online courses make it possible to collect certificates from many providers, yet a pile of unrelated badges says little about direction. One college asks learners to group courses around a goal and demonstrate how the skills combine in a project. The connecting work turns fragments into an intelligible learning route.`,`turns fragments into an intelligible learning route`,`Общий практический проект связывает разрозненные сертификаты в понятную траекторию обучения.`],[`Automation Changes Tasks Before Whole Jobs`,`When a company introduced software for routine invoices, its finance assistants did not disappear. They spent less time copying figures and more time investigating unusual cases or explaining them to clients. Preparing workers for change therefore meant analysing shifting tasks, not predicting that an entire occupation would vanish overnight.`,`analysing shifting tasks, not predicting that an entire occupation would vanish`,`Автоматизация перераспределила обязанности внутри профессии, поэтому обучение должно учитывать изменения задач.`],[`Students Help Define a Real Problem`,`An engineering course partnered with a care home that initially requested an app for residents. Interviews showed that unreliable wireless access and tiny buttons were the more immediate barriers. Students revised the brief before building anything, learning that professional skill includes questioning the proposed solution, not merely delivering it efficiently.`,`revised the brief before building anything`,`Исследование потребностей изменило исходный заказ и предотвратило создание неподходящего приложения.`],[`Human Judgement Remains Assessable`,`A class may use translation software during some assignments, but students must annotate where they accepted or rejected its suggestions. Teachers assess the reasoning behind those choices alongside the final text. The tool is neither secretly banned nor treated as an authority; its use becomes visible evidence of editorial judgement.`,`its use becomes visible evidence of editorial judgement`,`Комментарии к предложениям программы позволяют оценить самостоятельные редакторские решения ученика.`],[`Mentoring Works in Both Directions`,`A manufacturing firm paired experienced technicians with younger employees who knew newer modelling software. The technicians shared safety judgement and knowledge of unusual failures, while their partners demonstrated digital shortcuts. Calling both participants mentors changed the relationship from remedial training into reciprocal professional learning.`,`both participants mentors changed the relationship`,`Взаимное наставничество объединяет практический опыт старших сотрудников и цифровые навыки младших.`],[`Reflection Converts Experience Into Evidence`,`After a community internship, students once submitted only a record of hours. They now analyse one decision, the evidence available at the time and what they would change. Two placements can involve different duties, yet this reflection lets both demonstrate transferable learning rather than attendance alone.`,`demonstrate transferable learning rather than attendance alone`,`Анализ принятого решения показывает переносимый навык, а не просто количество проведённых часов.`]]})]);export{o as READING_TASK10_SETS};